313  static void processCertificateElements(struct ndpi_detection_module_struct *ndpi_struct,
   314                                         struct ndpi_flow_struct *flow,
   315                                         u_int16_t p_offset, u_int16_t certificate_len) {
   316    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
   317    u_int16_t num_found = 0, i;
   318    char buffer[64] = { '\0' }, rdnSeqBuf[2048];
   319    u_int rdn_len = 0;
   320
   321    rdnSeqBuf[0] = '\0';
   322
   323  #ifdef DEBUG_TLS
   324    printf("[TLS] %s() [offset: %u][certificate_len: %u]\n", __FUNCTION__, p_offset, certificate_len);
   325  #endif
   326
   327    /* Check after handshake protocol header (5 bytes) and message header (4 bytes) */
   328    for(i = p_offset; i < certificate_len; i++) {
   329      /*
   330        See https://www.ibm.com/support/knowledgecenter/SSFKSJ_7.5.0/com.ibm.mq.sec.doc/q009860_.htm
   331        for X.509 certificate labels
   332      */
   333      if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x03)) {
   334        /* Common Name */
   335        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "CN");
   336        if(rc == -1) break;
   337
   338  #ifdef DEBUG_TLS
   339        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "Common Name", buffer);
   340  #endif
   341      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x06)) {
   342        /* Country */
   343        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "C");
   344        if(rc == -1) break;
   345
   346  #ifdef DEBUG_TLS
   347        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "Country", buffer);
   348  #endif
   349      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x07)) {
   350        /* Locality */
   351        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "L");
   352        if(rc == -1) break;
   353
   354  #ifdef DEBUG_TLS
   355        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "Locality", buffer);
   356  #endif
   357      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x08)) {
   358        /* State or Province */
   359        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "ST");
   360        if(rc == -1) break;
   361
   362  #ifdef DEBUG_TLS
   363        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "State or Province", buffer);
   364  #endif
   365      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x0a)) {
   366        /* Organization Name */
   367        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "O");
   368        if(rc == -1) break;
   369
   370  #ifdef DEBUG_TLS
   371        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "Organization Name", buffer);
   372  #endif
   373
   374      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x04) && (packet->payload[i+2] == 0x0b)) {
   375        /* Organization Unit */
   376        int rc = extractRDNSequence(packet, i, buffer, sizeof(buffer), rdnSeqBuf, &rdn_len, sizeof(rdnSeqBuf), "OU");
   377        if(rc == -1) break;
   378
   379  #ifdef DEBUG_TLS
   380        printf("[TLS] %s() [%s][%s: %s]\n", __FUNCTION__, (num_found == 0) ? "Subject" : "Issuer", "Organization Unit", buffer);
   381  #endif
   382      } else if((packet->payload[i] == 0x30) && (packet->payload[i+1] == 0x1e) && (packet->payload[i+2] == 0x17)) {
   383        /* Certificate Validity */
   384        u_int8_t len = packet->payload[i+3];
   385        u_int offset = i+4;
   386
   387        if(num_found == 0) {
   388          num_found++;
   389
   390  #ifdef DEBUG_TLS
   391          printf("[TLS] %s() IssuerDN [%s]\n", __FUNCTION__, rdnSeqBuf);
   392  #endif
   393
   394          if(rdn_len && (flow->protos.tls_quic.issuerDN == NULL)) {
   395            flow->protos.tls_quic.issuerDN = ndpi_strdup(rdnSeqBuf);
   396            if(ndpi_is_printable_string(rdnSeqBuf, rdn_len) == 0) {
   397              ndpi_set_risk(ndpi_struct, flow, NDPI_INVALID_CHARACTERS);
   398            }
   399          }
   400
   401          rdn_len = 0; /* Reset buffer */
   402        }
   403
   404        if((offset+len) < packet->payload_packet_len) {
   405          char utcDate[32];
   406
   407  #ifdef DEBUG_TLS
   408          u_int j;
   409
   410          printf("[CERTIFICATE] notBefore [len: %u][", len);
   411          for(j=0; j<len; j++) printf("%c", packet->payload[i+4+j]);
   412          printf("]\n");
   413  #endif
   414
   415          if(len < (sizeof(utcDate)-1)) {
   416            struct tm utc;
   417            utc.tm_isdst = -1; /* Not set by strptime */
   418
   419            strncpy(utcDate, (const char*)&packet->payload[i+4], len);
   420            utcDate[len] = '\0';
   421
   422            /* 141021000000Z */
   423            if(strptime(utcDate, "%y%m%d%H%M%SZ", &utc) != NULL) {
   424              flow->protos.tls_quic.notBefore = timegm(&utc);
   425  #ifdef DEBUG_TLS
   426              printf("[CERTIFICATE] notBefore %u [%s]\n",
   427                     flow->protos.tls_quic.notBefore, utcDate);
   428  #endif
   429            }
   430          }
   431
   432          offset += len;
   433
   434          if((offset+1) < packet->payload_packet_len) {
   435            len = packet->payload[offset+1];
   436
   437            offset += 2;
   438
   439            if((offset+len) < packet->payload_packet_len) {
   440              u_int32_t time_sec = packet->current_time_ms / 1000;
   441  #ifdef DEBUG_TLS
   442              u_int j;
   443
   444              printf("[CERTIFICATE] notAfter [len: %u][", len);
   445              for(j=0; j<len; j++) printf("%c", packet->payload[offset+j]);
   446              printf("]\n");
   447  #endif
   448
   449              if(len < (sizeof(utcDate)-1)) {
   450                struct tm utc;
   451                utc.tm_isdst = -1; /* Not set by strptime */
   452
   453                strncpy(utcDate, (const char*)&packet->payload[offset], len);
   454                utcDate[len] = '\0';
   455
   456                /* 141021000000Z */
   457                if(strptime(utcDate, "%y%m%d%H%M%SZ", &utc) != NULL) {
   458                  flow->protos.tls_quic.notAfter = timegm(&utc);
   459  #ifdef DEBUG_TLS
   460                  printf("[CERTIFICATE] notAfter %u [%s]\n",
   461                         flow->protos.tls_quic.notAfter, utcDate);
   462  #endif
   463                }
   464              }
   465
   466              if(flow->protos.tls_quic.notBefore > TLS_LIMIT_DATE)
   467                if((flow->protos.tls_quic.notAfter-flow->protos.tls_quic.notBefore) > TLS_THRESHOLD)
   468                  ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_CERT_VALIDITY_TOO_LONG); /* Certificate validity longer than 13 months*/
   469
   470              if((time_sec < flow->protos.tls_quic.notBefore)
   471                 || (time_sec > flow->protos.tls_quic.notAfter))
   472                ndpi_set_risk(ndpi_struct, flow, NDPI_TLS_CERTIFICATE_EXPIRED); /* Certificate expired */
   473            }
   474          }
   475        }
   476      } else if((packet->payload[i] == 0x55) && (packet->payload[i+1] == 0x1d) && (packet->payload[i+2] == 0x11)) {
   477        /* Organization OID: 2.5.29.17 (subjectAltName) */
   478        u_int8_t matched_name = 0;
   479
   480        /* If the client hello was not observed or the requested name was missing, there is no need to trigger an alert */
   481        if(flow->host_server_name[0] == '\0')
   482          matched_name = 1;
   483
   484  #ifdef DEBUG_TLS
   485        printf("******* [TLS] Found subjectAltName\n");
   486  #endif
   487
   488        i += 3 /* skip the initial patten 55 1D 11 */;
   489
   490        /* skip the first type, 0x04 == BIT STRING, and jump to it's length */
   491        if(packet->payload[i] == 0x04) i++; else i += 4; /* 4 bytes, with the last byte set to 04 */
   492
   493        if(i < packet->payload_packet_len) {
   494          i += (packet->payload[i] & 0x80) ? (packet->payload[i] & 0x7F) : 0; /* skip BIT STRING length */
   495          if(i < packet->payload_packet_len) {
   496            i += 2; /* skip the second type, 0x30 == SEQUENCE, and jump to it's length */
   497            if(i < packet->payload_packet_len) {
   498              i += (packet->payload[i] & 0x80) ? (packet->payload[i] & 0x7F) : 0; /* skip SEQUENCE length */
   499              i++;
   500
   501              while(i < packet->payload_packet_len) {
   502                u_int8_t general_name_type = packet->payload[i];
   503
   504                if((general_name_type == 0x81)    /* rfc822Name */
   505                   || (general_name_type == 0x82) /* dNSName    */
   506                   || (general_name_type == 0x87) /* ipAddress  */
   507                   )
   508                  {
   509                  if((i < (packet->payload_packet_len - 1))
   510                     && ((i + packet->payload[i + 1] + 2) < packet->payload_packet_len)) {
   511                    u_int8_t len = packet->payload[i + 1];
   512                    char dNSName[256];
   513
   514                    i += 2;
   515
   516                    /* The check "len > sizeof(dNSName) - 1" will be always false. If we add it,
   517                       the compiler is smart enough to detect it and throws a warning */
   518                    if((len == 0 /* Looks something went wrong */)
   519                       || ((i+len) > packet->payload_packet_len))
   520                      break;
   521
   522                    if(general_name_type == 0x87) {
   523                      if(len == 4 /* IPv4 */) {
   524                        snprintf(dNSName, sizeof(dNSName), "%u.%u.%u.%u",
   525                                 packet->payload[i] & 0xFF,
   526                                 packet->payload[i+1] & 0xFF,
   527                                 packet->payload[i+2] & 0xFF,
   528                                 packet->payload[i+3] & 0xFF);
   529                      } else {
   530                        /*
   531                           TODO add IPv6 support when able to have
   532                           a pcap file for coding
   533                        */
   534                      }
   535                    } else {
   536                      strncpy(dNSName, (const char*)&packet->payload[i], len);
   537                      dNSName[len] = '\0';
   538                    }
   539
   540                    cleanupServerName(dNSName, len);
   541
   542  #if DEBUG_TLS
   543                    printf("[TLS] dNSName %s [%s][len: %u][leftover: %d]\n", dNSName,
   544                           flow->host_server_name, len,
   545                           packet->payload_packet_len-i-len);
   546  #endif
   547                    if(ndpi_is_printable_string(dNSName, len) == 0)
   548                      ndpi_set_risk(ndpi_struct, flow, NDPI_INVALID_CHARACTERS);
   549
   550                    if(matched_name == 0) {
   551  #if DEBUG_TLS
   552                      printf("[TLS] Trying to match '%s' with '%s'\n",
   553                             flow->host_server_name,
   554                             dNSName);
   555  #endif
   556
   557                      if(flow->host_server_name[0] == '\0') {
   558                        matched_name = 1; /* No SNI */
   559                      } else if(dNSName[0] == '*') {
   560                        char * label = strstr(flow->host_server_name, &dNSName[1]);
   561
   562                        if(label != NULL) {
   563                          char * first_dot = strchr(flow->host_server_name, '.');
   564
   565                          if(first_dot == NULL || first_dot >= label) {
   566                            matched_name = 1;
   567                          }
   568                        }
   569                      }
   570                      else if(strcmp(flow->host_server_name, dNSName) == 0) {
   571                        matched_name = 1;
   572                      }
   573                    }
   574
   575                    if(flow->protos.tls_quic.server_names == NULL)
   576                      flow->protos.tls_quic.server_names = ndpi_strdup(dNSName),
   577                        flow->protos.tls_quic.server_names_len = strlen(dNSName);
   578                    else {
   579                      u_int16_t dNSName_len = strlen(dNSName);
   580                      u_int16_t newstr_len = flow->protos.tls_quic.server_names_len + dNSName_len + 1;
   581                      char *newstr = (char*)ndpi_realloc(flow->protos.tls_quic.server_names,
   582                                                         flow->protos.tls_quic.server_names_len+1, newstr_len+1);
   583
   584                      if(newstr) {
   585                        flow->protos.tls_quic.server_names = newstr;
   586                        flow->protos.tls_quic.server_names[flow->protos.tls_quic.server_names_len] = ',';
   587                        strncpy(&flow->protos.tls_quic.server_names[flow->protos.tls_quic.server_names_len+1],
   588                                dNSName, dNSName_len+1);
   589                        flow->protos.tls_quic.server_names[newstr_len] = '\0';
